mapper.select:
SELECT FROM t_exam_batch WHERE deleted = 0
AND status = #{status}
ORDER BY start_date DESC, id DESC

mapper.insert:
INSERT INTO t_exam_batch (
    batch_name, start_date, end_date, status, remark,
    deleted, created_at, created_by, updated_at, updated_by
) VALUES (
    #{batchName}, #{startDate}, #{endDate}, #{status}, #{remark},
    0, NOW(), #{createdBy}, NOW(), #{updatedBy}
)
